INSERT INTO documents (id, title, type, branch, semester, subject_code, subject_name, academic_year, exam_type, uploaded_by, uploader_emp_id, upload_date, file_size, file_url, download_count, description, curriculum, exam_date, syllabus_covered, questions_preview) VALUES
('doc-1', 'Design & Analysis of Algorithms - Mid-1 Question Paper', 'question_paper', 'CSE', 4, 'CS402PC', 'Design and Analysis of Algorithms', '2024-25', 'Mid-1', 'Dr. P. Murali Krishna (HOD - CSE)', 'KMCE-CSE-001', '2025-02-14', '2.4 MB', '/documents/DAA_Mid1_2025.pdf', 382, 'Official JNTUH R25 Mid-1 Question Paper covering Asymptotic Notations, Divide and Conquer, and Dynamic Programming principles.', 'R25', '2025-02-10', 'Units 1 and 2: Asymptotic analysis, Recurrence relations, Divide & Conquer (Merge/Quick Sort), Greedy method intro.', '{"sectionA": ["Define Big-O and Little-o notations with formal mathematical limits.", "State Master Theorem for divide-and-conquer recurrences with edge cases.", "Compare greedy choice property vs optimal substructure.", "Formulate the recurrence relation for Strassen matrix multiplication."], "sectionB": [{"qNum": "Q1 (a)", "text": "Solve the recurrence T(n) = 3T(n/4) + cn^2 using Master Theorem method and recursion tree method.", "marks": 5}, {"qNum": "Q1 (b)", "text": "Explain Huffman Coding algorithm and find optimal prefix codes for {a:45, b:13, c:12, d:16, e:9, f:5}.", "marks": 5}]}'),
('doc-2', 'Machine Learning Foundations - Mid-1 Question Paper', 'question_paper', 'CSM', 4, 'AI401PC', 'Machine Learning Foundations', '2024-25', 'Mid-1', 'Dr. S. Radhika Devi (HOD - CSM)', 'KMCE-CSM-001', '2025-02-16', '3.1 MB', '/documents/ML_Mid1_2025.pdf', 418, 'JNTUH R25 CSM curriculum exam focusing on Supervised Learning, Cost Functions, Regularization, and Gradient Descent.', 'R25', '2025-02-12', 'Units 1 and 2: Linear Regression, Logistic Regression, Loss Functions, Gradient Descent Variants, Overfitting and Regularization (L1/L2).', '{"sectionA": ["Explain Bias-Variance tradeoff with appropriate graphical representation.", "Why is MSE not suitable as a loss function for Logistic Regression?", "Differentiate between Batch Gradient Descent and Stochastic Gradient Descent (SGD).", "Explain L1 (Lasso) vs L2 (Ridge) regularization penalty terms."], "sectionB": [{"qNum": "Q1 (a)", "text": "Derive the closed-form Normal Equation for Multivariate Linear Regression theta = (X^T X)^-1 X^T y.", "marks": 5}, {"qNum": "Q1 (b)", "text": "Explain decision tree splitting metrics (Entropy, Information Gain, and Gini Impurity).", "marks": 5}]}'),
('doc-3', 'Microprocessors & Microcontrollers - Mid-1 Exam Paper', 'question_paper', 'ECE', 4, 'EC403PC', 'Microprocessors & Microcontrollers', '2024-25', 'Mid-1', 'Dr. K. Venkat Rao (HOD - ECE)', 'KMCE-ECE-001', '2025-02-15', '2.8 MB', '/documents/MPMC_Mid1_2025.pdf', 290, 'Comprehensive question paper covering 8086 Microprocessor architecture, addressing modes, and 8051 microcontroller hardware.', 'R25', '2025-02-11', 'Units 1 and 2: 8086 Internal Architecture, Bus Interface Unit (BIU), Execution Unit (EU), Interrupts, Memory Segmentation.', '{"sectionA": ["Explain memory segmentation in 8086 microprocessor and its advantages.", "What are the flags present in 8086 flag register?", "Explain physical address generation formula in 8086.", "Differentiate between Microprocessor and Microcontroller architectures."], "sectionB": [{"qNum": "Q1 (a)", "text": "Draw and explain the internal architectural block diagram of 8086 microprocessor in detail.", "marks": 5}, {"qNum": "Q1 (b)", "text": "Explain various addressing modes of 8086 with assembly language examples.", "marks": 5}]}'),
('doc-4', 'Database Management Systems - Lesson Plan & Schedule', 'lesson_plan', 'CSE', 4, 'CS403PC', 'Database Management Systems', '2024-25', 'Mid-1', 'Prof. Ananya Varma', 'KMCE-CSE-004', '2025-01-08', '1.2 MB', '/documents/DBMS_LessonPlan_2025.pdf', 512, 'Unit-by-unit comprehensive lecture distribution schedule for JNTUH R25 DBMS course.', 'R25', '2025-01-06', 'All Units 1-5: ER modeling, Relational Algebra, SQL DDL/DML, Normalization (1NF to BCNF), ACID Properties, Transactions, Indexing (B+ Trees).', '{"sectionA": ["Unit 1: Entity-Relationship modeling and Relational data model", "Unit 2: SQL queries, nested subqueries, views, integrity constraints", "Unit 3: Normalization algorithms: 1NF, 2NF, 3NF, BCNF, 4NF"], "sectionB": [{"qNum": "Topic 1", "text": "Relational Calculus and Relational Algebra Equivalence rules", "marks": 0}]}');
