INSERT INTO courses (id, course_code, course_name, branch, semester, credits, instructor_name, instructor_emp_id, department, total_lectures, modules, reference_books) VALUES
('crs-1', 'CS402PC', 'Design and Analysis of Algorithms', 'CSE', 4, 4, 'Dr. P. Murali Krishna', 'KMCE-CSE-001', 'CSE', 48, '[{"unit": 1, "title": "Introduction & Asymptotic Analysis", "topics": ["Algorithm definition", "Order of growth", "Big-O, Omega, Theta notations", "Recurrence relations", "Master theorem"], "hours": 10}, {"unit": 2, "title": "Divide and Conquer & Greedy Method", "topics": ["Merge Sort", "Quick Sort", "Knapsack problem", "Huffman codes", "Job sequencing"], "hours": 10}, {"unit": 3, "title": "Dynamic Programming", "topics": ["0/1 Knapsack", "Matrix chain multiplication", "Longest Common Subsequence", "All-Pairs Shortest Path (Floyd-Warshall)"], "hours": 10}]', '["Introduction to Algorithms - Cormen, Leiserson, Rivest, Stein (CLRS)", "Fundamentals of Computer Algorithms - Ellis Horowitz, Sartaj Sahni"]'),
('crs-2', 'AI401PC', 'Machine Learning Foundations', 'CSM', 4, 4, 'Dr. S. Radhika Devi', 'KMCE-CSM-001', 'CSM', 50, '[{"unit": 1, "title": "Supervised Learning & Regression", "topics": ["Linear regression", "Cost functions", "Gradient descent", "Polynomial features", "Regularization (Ridge/Lasso)"], "hours": 12}, {"unit": 2, "title": "Classification Algorithms", "topics": ["Logistic regression", "Decision trees", "Random forests", "Support Vector Machines (SVM)", "Evaluation metrics"], "hours": 12}]', '["Pattern Recognition and Machine Learning - Christopher Bishop", "Hands-On Machine Learning - Aurelien Geron"]');
